/// Apply a packed-polynomial BFV Galois automorphism through the registered exact RNS corridor.
///
/// The evaluator chain is derived from the registered production BFV profile,
/// so production callers cannot supply an alternate chain with a different
/// public digest.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered, the
/// ciphertext or Galois key does not match the parameter set, or registered RNS
/// validation fails.
pub fn apply_galois_automorphism_ciphertext_registered_rns_exact(
    params: &BfvParameters,
    galois_key: &BfvGaloisKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    let rns_chain = registered_bfv_rns_modulus_chain(params)?;
    apply_galois_automorphism_ciphertext_rns_exact(params, &rns_chain, galois_key, ciphertext)
}

/// Encode a full BFV packed-slot plaintext into polynomial coefficients.
///
/// The registered RAM-LFE profile has `t = 257` and `n = 64`, so `t = 1 mod
/// 2n` and the plaintext ring splits into `n` CRT slots. This helper performs
/// deterministic interpolation over those CRT points and returns coefficients
/// in `Z_t[x] / (x^n + 1)`, ready to pass to [`encrypt_from_seed`].
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not batchable, the slot count
/// is not exactly `polynomial_degree`, or any slot is outside the plaintext
/// modulus.
pub fn encode_packed_plaintext_slots(
    params: &BfvParameters,
    slots: &[u64],
) -> Result<Vec<u64>, BfvError> {
    let points = packed_plaintext_evaluation_points(params)?;
    if slots.len() != params.degree() {
        return Err(BfvError::ShapeMismatch(format!(
            "packed plaintext expected {} slots, found {}",
            params.polynomial_degree,
            slots.len()
        )));
    }
    validate_plaintext(params, slots)?;

    let modulus = params.plaintext_modulus;
    let degree = params.degree();
    let mut coefficients = vec![0_u64; degree];
    for (slot_index, (&slot_value, &point)) in slots.iter().zip(&points).enumerate() {
        let mut basis = vec![1_u64];
        let mut denominator = 1_u64;
        for (other_index, &other_point) in points.iter().enumerate() {
            if other_index == slot_index {
                continue;
            }
            basis = multiply_plaintext_linear_factor(&basis, other_point, modulus);
            denominator = mul_mod_u64(
                denominator,
                sub_mod_u64(point, other_point, modulus),
                modulus,
            );
        }
        let inverse_denominator = mod_inv_prime_u64(denominator, modulus).ok_or_else(|| {
            BfvError::InvalidParameters(
                "packed plaintext interpolation denominator is not invertible".to_owned(),
            )
        })?;
        let scale = mul_mod_u64(slot_value, inverse_denominator, modulus);
        for (coefficient, basis_coefficient) in coefficients.iter_mut().zip(&basis) {
            *coefficient = add_mod_u64(
                *coefficient,
                mul_mod_u64(*basis_coefficient, scale, modulus),
                modulus,
            );
        }
    }
    Ok(coefficients)
}

/// Decode a full BFV packed-slot plaintext from polynomial coefficients.
///
/// This is the inverse of [`encode_packed_plaintext_slots`] for batchable
/// parameter sets. It evaluates the plaintext polynomial at the canonical
/// odd-power CRT points in `Z_t`.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not batchable, the plaintext
/// coefficient count is not exactly `polynomial_degree`, or any coefficient is
/// outside the plaintext modulus.
pub fn decode_packed_plaintext_slots(
    params: &BfvParameters,
    plaintext: &[u64],
) -> Result<Vec<u64>, BfvError> {
    let points = packed_plaintext_evaluation_points(params)?;
    if plaintext.len() != params.degree() {
        return Err(BfvError::ShapeMismatch(format!(
            "packed plaintext expected {} coefficients, found {}",
            params.polynomial_degree,
            plaintext.len()
        )));
    }
    validate_plaintext(params, plaintext)?;
    Ok(points
        .iter()
        .map(|&point| evaluate_plaintext_polynomial_mod(plaintext, point, params.plaintext_modulus))
        .collect())
}

/// Return the packed-slot permutation induced by a Galois automorphism.
///
/// For the canonical slot order used by [`encode_packed_plaintext_slots`], the
/// returned vector maps each output slot index to the input slot index that
/// appears there after applying `x -> x^k`.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not batchable or
/// `automorphism_power` is not a canonical BFV Galois automorphism power.
pub fn packed_galois_slot_permutation(
    params: &BfvParameters,
    automorphism_power: u32,
) -> Result<Vec<usize>, BfvError> {
    packed_plaintext_root(params)?;
    let power = validate_galois_automorphism_power(params, automorphism_power)?;
    let degree = params.degree();
    let cyclotomic_order = degree.checked_mul(2).ok_or_else(|| {
        BfvError::InvalidParameters(
            "BFV packed-slot cyclotomic order exceeds deterministic bounds".to_owned(),
        )
    })?;
    (0..degree)
        .map(|slot| {
            let exponent = slot
                .checked_mul(2)
                .and_then(|value| value.checked_add(1))
                .and_then(|value| value.checked_mul(power))
                .map(|value| value % cyclotomic_order)
                .ok_or_else(|| {
                    BfvError::InvalidParameters(
                        "BFV packed-slot permutation exponent exceeds deterministic bounds"
                            .to_owned(),
                    )
                })?;
            Ok((exponent - 1) / 2)
        })
        .collect()
}

/// Return the Galois automorphism power for a canonical packed-slot left rotation.
///
/// The registered packed slot order is the canonical odd-power CRT order used
/// by [`encode_packed_plaintext_slots`]. Not every cyclic left rotation in that
/// order is representable by one BFV Galois automorphism. This helper searches
/// the deterministic automorphism surface and fails closed when the requested
/// rotation cannot be expressed by a single public Galois key.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not batchable, the requested
/// rotation is zero, or no single Galois automorphism matches the requested
/// packed-slot rotation.
pub fn packed_left_rotation_galois_automorphism_power(
    params: &BfvParameters,
    rotation_steps: u32,
) -> Result<u32, BfvError> {
    let degree = params.degree();
    let normalized_steps = normalize_packed_rotation_steps(params, rotation_steps)?;
    let expected = (0..degree)
        .map(|slot| (slot + normalized_steps) % degree)
        .collect::<Vec<_>>();
    for power_u32 in canonical_galois_automorphism_powers(params)? {
        if packed_galois_slot_permutation(params, power_u32)? == expected {
            return Ok(power_u32);
        }
    }
    Err(BfvError::InvalidParameters(format!(
        "packed RotateLeft by {rotation_steps} slots is not representable by one BFV Galois automorphism"
    )))
}

/// Return every Galois automorphism power required for a packed left rotation.
///
/// Single-automorphism rotations return one power. Other rotations return a
/// deterministic ascending key schedule that can be evaluated by masking and
/// summing public Galois-key switched ciphertexts.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not batchable or the
/// requested rotation is zero/effectively a full packed-slot cycle.
pub fn packed_left_rotation_galois_automorphism_powers(
    params: &BfvParameters,
    rotation_steps: u32,
) -> Result<Vec<u32>, BfvError> {
    packed_left_rotation_galois_schedule(params, rotation_steps).map(|schedule| {
        schedule
            .into_iter()
            .map(|(automorphism_power, _mask)| automorphism_power)
            .collect()
    })
}

/// Rotate a packed BFV ciphertext left with a public Galois key.
///
/// This applies a canonical packed-slot left rotation only when the requested
/// `rotation_steps` maps to the supplied Galois key. Unsupported rotations fail
/// closed instead of falling back to an unrelated permutation.
///
/// # Errors
/// Returns [`BfvError`] when the rotation is not representable by one Galois
/// automorphism, the key power does not match the requested rotation, or the
/// ciphertext/key material is malformed for the parameter set.
pub fn rotate_packed_ciphertext_slots_left(
    params: &BfvParameters,
    galois_key: &BfvGaloisKey,
    ciphertext: &BfvCiphertext,
    rotation_steps: u32,
) -> Result<BfvCiphertext, BfvError> {
    let expected_power = packed_left_rotation_galois_automorphism_power(params, rotation_steps)?;
    if galois_key.automorphism_power != expected_power {
        return Err(BfvError::InvalidParameters(format!(
            "packed RotateLeft by {rotation_steps} slots requires Galois automorphism power {expected_power}, found {}",
            galois_key.automorphism_power
        )));
    }
    apply_galois_automorphism_ciphertext(params, galois_key, ciphertext)
}

/// Rotate a packed BFV ciphertext left with a public Galois-key schedule.
///
/// This helper supports any non-zero cyclic packed-slot rotation for the
/// canonical CRT slot order. If the rotation is not a single automorphism, it
/// applies every required public Galois key, masks the slots contributed by
/// that automorphism with a packed plaintext selector, and adds the masked
/// ciphertexts. Evaluators never need the BFV secret key.
///
/// # Errors
/// Returns [`BfvError`] when the rotation is invalid, required Galois keys are
/// missing or malformed, or ciphertext/plaintext-mask arithmetic fails.
pub fn rotate_packed_ciphertext_slots_left_with_galois_keys(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    rotation_steps: u32,
) -> Result<BfvCiphertext, BfvError> {
    params.validate()?;
    let schedule = packed_left_rotation_galois_schedule(params, rotation_steps)?;
    validate_galois_key_set_metadata(params, galois_keys, "packed RotateLeft")?;
    validate_ciphertext(params, ciphertext)?;
    validate_galois_key_set_entries(params, galois_keys)?;
    let mut output: Option<BfvCiphertext> = None;
    for (automorphism_power, mask_slots) in schedule {
        let galois_key = galois_keys
            .iter()
            .find(|key| key.automorphism_power == automorphism_power)
            .ok_or_else(|| {
                BfvError::InvalidParameters(format!(
                    "missing BFV Galois key for packed RotateLeft automorphism power {automorphism_power}"
                ))
            })?;
        let transformed = apply_galois_automorphism_ciphertext(params, galois_key, ciphertext)?;
        let mask_plaintext = encode_packed_plaintext_slots(params, &mask_slots)?;
        let masked = multiply_plaintext_polynomial(params, &transformed, &mask_plaintext)?;
        output = Some(match output {
            Some(accumulator) => add_ciphertexts(params, &accumulator, &masked)?,
            None => masked,
        });
    }
    output.ok_or_else(|| {
        BfvError::InvalidParameters(
            "packed RotateLeft produced an empty Galois key schedule".to_owned(),
        )
    })
}

/// Rotate a rounded BFV packed ciphertext left with bounded-noise Galois keys.
///
/// This mirrors [`rotate_packed_ciphertext_slots_left_with_galois_keys`] for
/// the rounded BFV-RNS migration path: each scheduled automorphism uses
/// bounded-noise key switching, then a public packed plaintext selector masks
/// the slots contributed by that automorphism before the masked ciphertexts
/// are accumulated.
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow, the rotation is
/// invalid, required Galois keys are missing or malformed, or ciphertext/
/// plaintext-mask arithmetic fails.
pub fn rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    rotation_steps: u32,
) -> Result<BfvCiphertext, BfvError> {
    let schedule = packed_left_rotation_galois_schedule(params, rotation_steps)?;
    validate_galois_key_set_metadata(params, galois_keys, "bounded-noise packed RotateLeft")?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    validate_ciphertext(params, ciphertext)?;
    validate_galois_key_set_entries(params, galois_keys)?;
    let mut output: Option<BfvCiphertext> = None;
    for (automorphism_power, mask_slots) in schedule {
        let galois_key = galois_keys
            .iter()
            .find(|key| key.automorphism_power == automorphism_power)
            .ok_or_else(|| {
                BfvError::InvalidParameters(format!(
                    "missing BFV Galois key for bounded-noise packed RotateLeft automorphism power {automorphism_power}"
                ))
            })?;
        let transformed =
            apply_galois_automorphism_ciphertext_bounded_noise(params, galois_key, ciphertext)?;
        let mask_plaintext = encode_packed_plaintext_slots(params, &mask_slots)?;
        let masked =
            multiply_plaintext_polynomial_bounded_noise(params, &transformed, &mask_plaintext)?;
        output = Some(match output {
            Some(accumulator) => add_ciphertexts(params, &accumulator, &masked)?,
            None => masked,
        });
    }
    output.ok_or_else(|| {
        BfvError::InvalidParameters(
            "bounded-noise packed RotateLeft produced an empty Galois key schedule".to_owned(),
        )
    })
}

/// Rotate a rounded BFV packed ciphertext left through exact RNS bridges.
///
/// This is the RNS counterpart of
/// [`rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise`].
/// Every scheduled bounded-noise Galois switch, public packed-selector product,
/// and accumulator addition runs through the guarded RNS exact bridge.
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow, the rotation is
/// invalid, required Galois keys are missing or malformed, the RNS chain is too
/// narrow, or ciphertext/plaintext-mask arithmetic fails.
pub fn rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise_rns_exact(
    params: &BfvParameters,
    rns_chain: &BfvRnsModulusChain,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    rotation_steps: u32,
) -> Result<BfvCiphertext, BfvError> {
    let schedule = packed_left_rotation_galois_schedule(params, rotation_steps)?;
    validate_galois_key_set_metadata(params, galois_keys, "bounded-noise RNS packed RotateLeft")?;
    validate_bounded_noise_rns_evaluator_corridor(params, rns_chain)?;
    validate_ciphertext(params, ciphertext)?;
    validate_galois_key_set_entries(params, galois_keys)?;
    let mut output: Option<BfvCiphertext> = None;
    for (automorphism_power, mask_slots) in schedule {
        let galois_key = galois_keys
            .iter()
            .find(|key| key.automorphism_power == automorphism_power)
            .ok_or_else(|| {
                BfvError::InvalidParameters(format!(
                    "missing BFV Galois key for bounded-noise RNS packed RotateLeft automorphism power {automorphism_power}"
                ))
            })?;
        let transformed = apply_galois_automorphism_ciphertext_bounded_noise_rns_exact(
            params, rns_chain, galois_key, ciphertext,
        )?;
        let mask_plaintext = encode_packed_plaintext_slots(params, &mask_slots)?;
        let masked = multiply_plaintext_polynomial_bounded_noise_rns_exact(
            params,
            rns_chain,
            &transformed,
            &mask_plaintext,
        )?;
        output = Some(match output {
            Some(accumulator) => {
                add_ciphertexts_rns_exact(params, rns_chain, &accumulator, &masked)?
            }
            None => masked,
        });
    }
    output.ok_or_else(|| {
        BfvError::InvalidParameters(
            "bounded-noise RNS packed RotateLeft produced an empty Galois key schedule".to_owned(),
        )
    })
}

/// Rotate a rounded BFV packed ciphertext through the registered exact RNS bridge.
///
/// This is the production-bound exact-reconstruction fallback for bounded
/// packed `RotateLeft`: the evaluator chain is derived from the registered BFV
/// profile before the public Galois schedule is evaluated.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered, rounded BFV
/// capacity is too narrow, the rotation is invalid, required Galois keys are
/// missing or malformed, or ciphertext/plaintext-mask arithmetic fails.
pub fn rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise_registered_rns_exact(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    rotation_steps: u32,
) -> Result<BfvCiphertext, BfvError> {
    let rns_chain = registered_bfv_rns_modulus_chain(params)?;
    rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise_rns_exact(
        params,
        &rns_chain,
        galois_keys,
        ciphertext,
        rotation_steps,
    )
}

/// Rotate a rounded BFV packed ciphertext left through target-limb RNS bridges.
///
/// This is the basis-extension counterpart of
/// [`rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise_rns_exact`].
/// Each scheduled Galois switch decomposes in `decomposition_chain`,
/// target-limb basis-extends into `evaluator_chain`, then uses the same guarded RNS
/// plaintext-selector products and accumulator additions as the exact RNS
/// packed rotation bridge.
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow, the rotation is
/// invalid, required Galois keys are missing or malformed, the evaluator chain
/// is too narrow, the decomposition chain is not an evaluator-chain prefix, or
/// ciphertext/plaintext-mask arithmetic fails.
pub fn rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise_rns_basis_extension_exact(
    params: &BfvParameters,
    decomposition_chain: &BfvRnsModulusChain,
    evaluator_chain: &BfvRnsModulusChain,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    rotation_steps: u32,
) -> Result<BfvCiphertext, BfvError> {
    let schedule = packed_left_rotation_galois_schedule(params, rotation_steps)?;
    validate_galois_key_set_metadata(
        params,
        galois_keys,
        "bounded-noise basis-extension RNS packed RotateLeft",
    )?;
    validate_bounded_noise_rns_basis_extension_corridor(
        params,
        decomposition_chain,
        evaluator_chain,
        "bounded-noise RNS packed RotateLeft decomposition",
    )?;
    validate_ciphertext(params, ciphertext)?;
    validate_galois_key_set_entries(params, galois_keys)?;
    let mut output: Option<BfvCiphertext> = None;
    for (automorphism_power, mask_slots) in schedule {
        let galois_key = galois_keys
            .iter()
            .find(|key| key.automorphism_power == automorphism_power)
            .ok_or_else(|| {
                BfvError::InvalidParameters(format!(
                    "missing BFV Galois key for bounded-noise basis-extension RNS packed RotateLeft automorphism power {automorphism_power}"
                ))
            })?;
        let transformed =
            apply_galois_automorphism_ciphertext_bounded_noise_rns_basis_extension_exact(
                params,
                decomposition_chain,
                evaluator_chain,
                galois_key,
                ciphertext,
            )?;
        let mask_plaintext = encode_packed_plaintext_slots(params, &mask_slots)?;
        let masked = multiply_plaintext_polynomial_bounded_noise_rns_exact(
            params,
            evaluator_chain,
            &transformed,
            &mask_plaintext,
        )?;
        output = Some(match output {
            Some(accumulator) => {
                add_ciphertexts_rns_exact(params, evaluator_chain, &accumulator, &masked)?
            }
            None => masked,
        });
    }
    output.ok_or_else(|| {
        BfvError::InvalidParameters(
            "bounded-noise basis-extension RNS packed RotateLeft produced an empty Galois key schedule"
                .to_owned(),
        )
    })
}

/// Rotate a rounded BFV packed ciphertext through the registered target-limb RNS bridge.
///
/// This is the production-oriented counterpart of
/// [`rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise_rns_basis_extension_exact`]:
/// the evaluator chain and key-switch source basis are derived from the
/// registered production BFV profile before any public Galois schedule is
/// applied.
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow, the rotation is
/// invalid, required Galois keys are missing or malformed, the parameter set is
/// not registered, or ciphertext/plaintext-mask arithmetic fails.
pub fn rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise_registered_rns_basis_extension_exact(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    rotation_steps: u32,
) -> Result<BfvCiphertext, BfvError> {
    let evaluator_chain = registered_bfv_rns_modulus_chain(params)?;
    let decomposition_chain =
        registered_bfv_key_switch_decomposition_chain_for_evaluator(params, &evaluator_chain)?;
    rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise_rns_basis_extension_exact(
        params,
        &decomposition_chain,
        &evaluator_chain,
        galois_keys,
        ciphertext,
        rotation_steps,
    )
}

/// Rotate a packed BFV ciphertext left with a public Galois-key schedule
/// through an exact RNS corridor.
///
/// This is the RNS exact counterpart of
/// [`rotate_packed_ciphertext_slots_left_with_galois_keys`]. Each public
/// Galois switch, plaintext mask product, and accumulator addition uses the
/// guarded registered-chain bridge.
///
/// # Errors
/// Returns [`BfvError`] when the rotation is invalid, required Galois keys are
/// missing or malformed, or the RNS chain is malformed or too narrow for exact
/// ciphertext-modulus arithmetic.
pub fn rotate_packed_ciphertext_slots_left_with_galois_keys_rns_exact(
    params: &BfvParameters,
    rns_chain: &BfvRnsModulusChain,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    rotation_steps: u32,
) -> Result<BfvCiphertext, BfvError> {
    params.validate()?;
    validate_rns_exact_evaluator_chain(params, rns_chain)?;
    let schedule = packed_left_rotation_galois_schedule(params, rotation_steps)?;
    validate_galois_key_set_metadata(params, galois_keys, "packed RotateLeft")?;
    validate_ciphertext(params, ciphertext)?;
    validate_galois_key_set_entries(params, galois_keys)?;
    let mut output: Option<BfvCiphertext> = None;
    for (automorphism_power, mask_slots) in schedule {
        let galois_key = galois_keys
            .iter()
            .find(|key| key.automorphism_power == automorphism_power)
            .ok_or_else(|| {
                BfvError::InvalidParameters(format!(
                    "missing BFV Galois key for packed RotateLeft automorphism power {automorphism_power}"
                ))
            })?;
        let transformed = apply_galois_automorphism_ciphertext_rns_exact(
            params, rns_chain, galois_key, ciphertext,
        )?;
        let mask_plaintext = encode_packed_plaintext_slots(params, &mask_slots)?;
        let masked = multiply_plaintext_polynomial_rns_exact(
            params,
            rns_chain,
            &transformed,
            &mask_plaintext,
        )?;
        output = Some(match output {
            Some(accumulator) => {
                add_ciphertexts_rns_exact(params, rns_chain, &accumulator, &masked)?
            }
            None => masked,
        });
    }
    output.ok_or_else(|| {
        BfvError::InvalidParameters(
            "packed RotateLeft produced an empty Galois key schedule".to_owned(),
        )
    })
}

/// Rotate a packed BFV ciphertext left through the registered exact RNS corridor.
///
/// The evaluator chain is derived from the registered production BFV profile
