    #[test]
    fn bfv_decomposition_digits_are_checked() {
        let params = params();
        assert_eq!(
            params
                .decomposition_digits()
                .expect("valid params have a deterministic digit count"),
            2
        );
        assert_eq!(
            bfv_key_switch_extra_residual_multiple_bound(&params)
                .expect("valid params have a deterministic key-switch residual bound"),
            65_520
        );

        let invalid = BfvParameters {
            decomposition_base_log: 0,
            ..params
        };
        let err = invalid
            .decomposition_digits()
            .expect_err("invalid decomposition base must fail before digit coverage");
        assert!(
            err.to_string().contains("decomposition_base_log"),
            "unexpected error: {err}"
        );

        let err = bfv_key_switch_extra_residual_multiple_bound(&invalid)
            .expect_err("key-switch residual bound must reject invalid digit parameters");
        assert!(
            err.to_string().contains("decomposition_base_log"),
            "unexpected error: {err}"
        );

        let err = validate_key_switch_entries(&invalid, &[], "test key")
            .expect_err("key-switch entry validation must reject invalid digit parameters");
        assert!(
            err.to_string().contains("decomposition_base_log"),
            "unexpected error: {err}"
        );

        let mut rng = derive_rng(b"bfv-decomposition-digits-test", b"invalid-base");
        let zero_secret = vec![0; params.degree()];
        let err = key_switch_entries_from_rng(&invalid, &zero_secret, &zero_secret, &mut rng)
            .expect_err("key-switch generation must reject invalid digit parameters");
        assert!(
            err.to_string().contains("decomposition_base_log"),
            "unexpected error: {err}"
        );

        let err = decompose_poly(&invalid, &zero_secret)
            .expect_err("polynomial decomposition must reject invalid digit parameters");
        assert!(
            err.to_string().contains("decomposition_base_log"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn public_key_validator_rejects_malformed_components() {
        let params = params();
        let wrong_length = BfvPublicKey {
            b: vec![0; params.degree() - 1],
            a: zero_poly(&params),
        };
        let err = validate_public_key(&params, &wrong_length)
            .expect_err("public-key component length drift must be rejected");
        assert!(
            err.to_string().contains("public key b length"),
            "unexpected error: {err}"
        );

        let mut out_of_modulus = BfvPublicKey {
            b: zero_poly(&params),
            a: zero_poly(&params),
        };
        out_of_modulus.a[0] = params.ciphertext_modulus;
        let err = validate_public_key(&params, &out_of_modulus)
            .expect_err("public-key coefficients outside modulus must be rejected");
        assert!(
            err.to_string().contains("public key a contains"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn public_key_secret_consistency_rejects_tampered_key_material() {
        let params = params();
        let (secret_key, public_key, _) =
            keygen_from_seed(&params, b"bfv-public-key-consistency-keygen").expect("keygen");

        validate_public_key_secret_consistency(&params, &secret_key, &public_key)
            .expect("generated public key is consistent with the secret key");

        let mut non_plaintext_residue = public_key.clone();
        non_plaintext_residue.b[0] =
            add_mod_u64(non_plaintext_residue.b[0], 1, params.ciphertext_modulus);
        let err =
            validate_public_key_secret_consistency(&params, &secret_key, &non_plaintext_residue)
                .expect_err("non-plaintext-multiple public-key residual must be rejected");
        assert!(
            err.to_string().contains("non-plaintext-multiple"),
            "unexpected error: {err}"
        );

        let mut oversized_residual = BfvPublicKey {
            b: zero_poly(&params),
            a: zero_poly(&params),
        };
        oversized_residual.b[0] = params.plaintext_modulus * 2;
        let err = validate_public_key_secret_consistency(&params, &secret_key, &oversized_residual)
            .expect_err("oversized public-key residual must be rejected");
        assert!(
            err.to_string().contains("BFV error bound"),
            "unexpected error: {err}"
        );

        let (wrong_secret, _, _) =
            keygen_from_seed(&params, b"bfv-public-key-consistency-wrong-secret")
                .expect("wrong keygen");
        let err = validate_public_key_secret_consistency(&params, &wrong_secret, &public_key)
            .expect_err("public key must reject an unrelated secret key");
        assert!(
            err.to_string().contains("residual"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn refresh_key_transcripts_reject_tampered_public_material() {
        let material = evaluation_key_adversarial_material();

        validate_rotation_key_zero_refresh_transcript(
            &material.params,
            &material.public_key,
            &material.rotation_key,
            b"bfv-eval-key-rotation",
        )
        .expect("generated rotation key matches its deterministic transcript");

        let err = validate_rotation_key_zero_refresh_transcript(
            &material.params,
            &material.public_key,
            &material.rotation_key,
            b"bfv-eval-key-rotation-wrong-seed",
        )
        .expect_err("wrong rotation transcript seed must be rejected");
        assert!(
            err.to_string()
                .contains("deterministic encrypted-zero transcript"),
            "unexpected error: {err}"
        );

        let err = validate_rotation_key_zero_refresh_transcript(
            &material.params,
            &material.public_key,
            &material.rotation_key,
            b"",
        )
        .expect_err("empty rotation transcript seed must be rejected");
        assert!(
            err.to_string().contains("must not be empty"),
            "unexpected error: {err}"
        );

        let oversized_rotation_seed = vec![0xA5; BFV_REFRESH_TRANSCRIPT_SEED_MAX_BYTES + 1];
        let err = validate_rotation_key_zero_refresh_transcript(
            &material.params,
            &material.public_key,
            &material.rotation_key,
            &oversized_rotation_seed,
        )
        .expect_err("oversized rotation transcript seed must be rejected");
        assert!(
            err.to_string().contains("maximum supported length"),
            "unexpected error: {err}"
        );

        let mut tampered_rotation = material.rotation_key.clone();
        tampered_rotation.zero_refresh.c0[0] = add_mod_u64(
            tampered_rotation.zero_refresh.c0[0],
            1,
            material.params.ciphertext_modulus,
        );
        let err = validate_rotation_key_zero_refresh_transcript(
            &material.params,
            &material.public_key,
            &tampered_rotation,
            b"bfv-eval-key-rotation",
        )
        .expect_err("tampered rotation refresh must be rejected by transcript validation");
        assert!(
            err.to_string()
                .contains("deterministic encrypted-zero transcript"),
            "unexpected error: {err}"
        );

        let bootstrap_seed = b"bfv-refresh-transcript-bootstrap";
        let bootstrap_key = bootstrap_key_with_max_refresh_rounds_from_seed(
            &material.params,
            &material.public_key,
            "bootstrap-refresh-key",
            2,
            bootstrap_seed,
        )
        .expect("bootstrap key");
        validate_bootstrap_key_zero_refresh_transcript(
            &material.params,
            &material.public_key,
            &bootstrap_key,
            bootstrap_seed,
        )
        .expect("generated bootstrap key matches its deterministic transcript");

        let err = validate_bootstrap_key_zero_refresh_transcript(
            &material.params,
            &material.public_key,
            &bootstrap_key,
            b"bfv-refresh-transcript-wrong-seed",
        )
        .expect_err("wrong bootstrap transcript seed must be rejected");
        assert!(
            err.to_string()
                .contains("deterministic encrypted-zero transcript"),
            "unexpected error: {err}"
        );

        let err = validate_bootstrap_key_zero_refresh_transcript(
            &material.params,
            &material.public_key,
            &bootstrap_key,
            b"",
        )
        .expect_err("empty bootstrap transcript seed must be rejected");
        assert!(
            err.to_string().contains("must not be empty"),
            "unexpected error: {err}"
        );

        let oversized_bootstrap_seed = vec![0x5A; BFV_REFRESH_TRANSCRIPT_SEED_MAX_BYTES + 1];
        let err = validate_bootstrap_key_zero_refresh_transcript(
            &material.params,
            &material.public_key,
            &bootstrap_key,
            &oversized_bootstrap_seed,
        )
        .expect_err("oversized bootstrap transcript seed must be rejected");
        assert!(
            err.to_string().contains("maximum supported length"),
            "unexpected error: {err}"
        );

        let mut tampered_bootstrap_round = bootstrap_key.clone();
        tampered_bootstrap_round.round_refreshes[1].c1[0] = add_mod_u64(
            tampered_bootstrap_round.round_refreshes[1].c1[0],
            1,
            material.params.ciphertext_modulus,
        );
        let err = validate_bootstrap_key_zero_refresh_transcript(
            &material.params,
            &material.public_key,
            &tampered_bootstrap_round,
            bootstrap_seed,
        )
        .expect_err("tampered bootstrap round refresh must be rejected");
        assert!(
            err.to_string().contains("round_refreshes[1]"),
            "unexpected error: {err}"
        );

        let mut drifted_key_id = bootstrap_key;
        drifted_key_id.key_id.push_str("-drift");
        let err = validate_bootstrap_key_zero_refresh_transcript(
            &material.params,
            &material.public_key,
            &drifted_key_id,
            bootstrap_seed,
        )
        .expect_err("bootstrap key-id drift must change the transcript");
        assert!(
            err.to_string().contains("zero_refresh"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn bootstrap_key_zero_refresh_proof_statement_digest_binds_public_material() {
        let material = evaluation_key_adversarial_material();
        let bootstrap_seed = b"bfv-bootstrap-proof-statement";
        let bootstrap_key = bootstrap_key_with_max_refresh_rounds_from_seed(
            &material.params,
            &material.public_key,
            "bootstrap-proof-key",
            2,
            bootstrap_seed,
        )
        .expect("bootstrap key");

        let digest = bootstrap_key_zero_refresh_proof_statement_digest(
            &material.params,
            &material.public_key,
            &bootstrap_key,
        )
        .expect("bootstrap proof statement digest");
        assert_eq!(
            digest,
            bootstrap_key_zero_refresh_proof_statement_digest(
                &material.params,
                &material.public_key,
                &bootstrap_key
            )
            .expect("repeat bootstrap proof statement digest")
        );

        let statement_material = BfvBootstrapKeyProofStatementMaterial {
            params: material.params,
            public_key: material.public_key.clone(),
            bootstrap_key: bootstrap_key.clone(),
        };
        let statement_bytes =
            norito::to_bytes(&statement_material).expect("encode bootstrap statement material");
        assert_eq!(
            digest,
            Hash::new_from_chunks(&[
                BFV_BOOTSTRAP_KEY_ZERO_REFRESH_PROOF_STATEMENT_DOMAIN,
                statement_bytes.as_slice(),
            ])
        );

        let bounded_digest = bootstrap_key_bounded_noise_zero_refresh_proof_statement_digest(
            &material.params,
            &material.public_key,
            &bootstrap_key,
        )
        .expect("bounded bootstrap proof statement digest");
        assert_ne!(
            digest, bounded_digest,
            "exact-lift and bounded-noise proof statements must be domain-separated"
        );

        let mut tampered_refresh = bootstrap_key;
        tampered_refresh.round_refreshes[1].c0[0] = add_mod_u64(
            tampered_refresh.round_refreshes[1].c0[0],
            1,
            material.params.ciphertext_modulus,
        );
        let tampered_digest = bootstrap_key_zero_refresh_proof_statement_digest(
            &material.params,
            &material.public_key,
            &tampered_refresh,
        )
        .expect("tampered but shape-valid bootstrap statement digest");
        assert_ne!(
            digest, tampered_digest,
            "proof statement digest must bind every refresh ciphertext"
        );
    }

    #[test]
    fn bootstrap_key_transcript_proof_statement_digest_binds_governance_inventory() {
        let material = evaluation_key_adversarial_material();
        let bootstrap_seed = b"bfv-bootstrap-transcript-proof-statement";
        let bootstrap_key = bootstrap_key_with_max_refresh_rounds_from_seed(
            &material.params,
            &material.public_key,
            "bootstrap-transcript-proof-key",
            2,
            bootstrap_seed,
        )
        .expect("bootstrap key");
        let bundle = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key.clone(),
            rotation_keys: vec![material.rotation_key.clone()],
            galois_keys: vec![material.galois_key.clone()],
            bootstrap_key: Some(bootstrap_key.clone()),
        };
        let rotation_transcripts = [BfvRotationKeyTranscriptSeed {
            rotation_steps: 1,
            seed: b"bfv-eval-key-rotation",
        }];
        let bootstrap_transcript = Some(BfvBootstrapKeyTranscriptSeed {
            key_id: "bootstrap-transcript-proof-key",
            max_refresh_rounds: 2,
            seed: bootstrap_seed,
        });

        let digest = bundle
            .bootstrap_key_zero_refresh_proof_statement_digest_for_transcript(
                &material.params,
                &material.public_key,
                &rotation_transcripts,
                bootstrap_transcript,
            )
            .expect("transcript-bound proof statement")
            .expect("bootstrap key is present");
        assert_eq!(
            digest,
            bundle
                .bootstrap_key_zero_refresh_proof_statement_digest_for_transcript(
                    &material.params,
                    &material.public_key,
                    &rotation_transcripts,
                    bootstrap_transcript,
                )
                .expect("repeat transcript-bound proof statement")
                .expect("bootstrap key is present")
        );

        let evaluation_key_digest = bundle.digest(&material.params).expect("bundle digest");
        let refresh_transcript_digest = bundle
            .refresh_transcript_digest(
                &material.params,
                &material.public_key,
                &rotation_transcripts,
                bootstrap_transcript,
            )
            .expect("refresh transcript digest");
        let statement_material = BfvBootstrapKeyTranscriptProofStatementMaterial {
            params: material.params,
            public_key: material.public_key.clone(),
            evaluation_key_digest,
            refresh_transcript_digest,
            bootstrap_transcript: BfvBootstrapKeyTranscriptDigestMaterial {
                key_id: "bootstrap-transcript-proof-key".to_string(),
                max_refresh_rounds: 2,
                seed: bootstrap_seed.to_vec(),
            },
            bootstrap_key: bootstrap_key.clone(),
        };
        let statement_bytes = norito::to_bytes(&statement_material)
            .expect("encode transcript-bound bootstrap statement material");
        assert_eq!(
            digest,
            Hash::new_from_chunks(&[
                BFV_BOOTSTRAP_KEY_TRANSCRIPT_ZERO_REFRESH_PROOF_STATEMENT_DOMAIN,
                statement_bytes.as_slice(),
            ])
        );

        let raw_digest = bootstrap_key_zero_refresh_proof_statement_digest(
            &material.params,
            &material.public_key,
            &bootstrap_key,
        )
        .expect("raw bootstrap-key statement");
        assert_ne!(
            digest, raw_digest,
            "policy proof statements must bind transcript inventory, not only bootstrap key material"
        );

        let wrong_bootstrap_seed = Some(BfvBootstrapKeyTranscriptSeed {
            key_id: "bootstrap-transcript-proof-key",
            max_refresh_rounds: 2,
            seed: b"bfv-bootstrap-transcript-proof-wrong-seed",
        });
        let err = bundle
            .bootstrap_key_zero_refresh_proof_statement_digest_for_transcript(
                &material.params,
                &material.public_key,
                &rotation_transcripts,
                wrong_bootstrap_seed,
            )
            .expect_err("wrong bootstrap transcript seed must be rejected");
        assert!(
            err.to_string()
                .contains("deterministic encrypted-zero transcript"),
            "unexpected error: {err}"
        );

        let mut drifted_bundle = bundle;
        drifted_bundle.galois_keys.clear();
        let drifted_digest = drifted_bundle
            .bootstrap_key_zero_refresh_proof_statement_digest_for_transcript(
                &material.params,
                &material.public_key,
                &rotation_transcripts,
                bootstrap_transcript,
            )
            .expect("drifted but shape-valid bundle statement")
            .expect("bootstrap key is present");
        assert_ne!(
            digest, drifted_digest,
            "proof statement digest must bind the full evaluation-key bundle digest"
        );
    }

