    #[test]
    fn rns_exact_ciphertext_modulus_polynomial_ops_match_scalar_q_ring() {
        let params = rns_exact_params();
        let chain = rns_exact_chain();
        chain
            .validate_exact_ciphertext_modulus_addition_coverage(&params)
            .expect("wide chain covers exact q-ring addition");
        chain
            .validate_exact_ciphertext_modulus_negacyclic_product_coverage(&params)
            .expect("wide chain covers exact q-ring multiplication");

        let lhs = vec![44, 7];
        let rhs = vec![12, 39];
        assert_eq!(
            chain
                .add_ciphertext_modulus_polynomials_exact(&params, &lhs, &rhs)
                .expect("exact RNS q-ring addition"),
            poly_add_mod(&params, &lhs, &rhs)
        );
        assert_eq!(
            chain
                .multiply_ciphertext_modulus_polynomials_negacyclic_exact(&params, &lhs, &rhs)
                .expect("exact RNS q-ring multiplication"),
            poly_mul_mod(&params, &lhs, &rhs)
        );

        let x = vec![0, 1];
        assert_eq!(
            chain
                .multiply_ciphertext_modulus_polynomials_negacyclic_exact(&params, &x, &x)
                .expect("x*x wraps as -1 in the negacyclic ring"),
            vec![params.ciphertext_modulus - 1, 0]
        );
    }

    #[test]
    fn rns_exact_ciphertext_evaluator_matches_scalar_baseline() {
        let params = rns_exact_params();
        let chain = rns_exact_chain();
        let (secret_key, public_key, relinearization_key) =
            keygen_from_seed(&params, b"bfv-rns-exact-ciphertext-keygen").expect("keygen");
        let lhs = encrypt_from_seed(
            &params,
            &public_key,
            &[params.plaintext_modulus - 1, 1],
            b"bfv-rns-exact-ciphertext-lhs",
        )
        .expect("encrypt lhs");
        let rhs = encrypt_from_seed(
            &params,
            &public_key,
            &[3, params.plaintext_modulus - 1],
            b"bfv-rns-exact-ciphertext-rhs",
        )
        .expect("encrypt rhs");

        let scalar_sum = add_ciphertexts(&params, &lhs, &rhs).expect("scalar add");
        let rns_sum =
            add_ciphertexts_rns_exact(&params, &chain, &lhs, &rhs).expect("RNS exact add");
        assert_eq!(rns_sum, scalar_sum);
        assert_eq!(
            &decrypt(&params, &secret_key, &rns_sum).expect("decrypt RNS sum")[..2],
            &[2, 0]
        );

        let scalar_difference = subtract_ciphertexts(&params, &lhs, &rhs).expect("scalar subtract");
        let rns_difference = subtract_ciphertexts_rns_exact(&params, &chain, &lhs, &rhs)
            .expect("RNS exact subtract");
        assert_eq!(rns_difference, scalar_difference);
        assert_eq!(
            &decrypt(&params, &secret_key, &rns_difference).expect("decrypt RNS difference")[..2],
            &[1, 2]
        );

        let scalar_product = multiply_ciphertexts(&params, &relinearization_key, &lhs, &rhs)
            .expect("scalar multiply");
        let rns_product =
            multiply_ciphertexts_rns_exact(&params, &chain, &relinearization_key, &lhs, &rhs)
                .expect("RNS exact multiply");
        assert_eq!(rns_product, scalar_product);
        assert_eq!(
            &decrypt(&params, &secret_key, &rns_product).expect("decrypt RNS product")[..2],
            &[3, 4]
        );
    }

    #[test]
    fn rns_polynomial_roundtrip_preserves_registered_ciphertext_coefficients() {
        let params = ram_lfe_bfv_parameters_v1();
        let chain = registered_bfv_rns_modulus_chain(&params).expect("registered chain");
        let mut coefficients = (0..params.degree())
            .map(|index| {
                let value = (u128::from(params.ciphertext_modulus - 1)
                    * u128::try_from(index + 17).expect("index fits"))
                    % u128::from(params.ciphertext_modulus);
                u64::try_from(value).expect("coefficient fits")
            })
            .collect::<Vec<_>>();
        coefficients[0] = 0;
        coefficients[1] = 1;
        coefficients[2] = RAM_LFE_BFV_PLAINTEXT_MODULUS;
        coefficients[3] = params.ciphertext_modulus - 1;

        let rns = chain
            .decompose_polynomial(&params, &coefficients)
            .expect("decompose polynomial into RNS");
        assert_eq!(rns.residues_by_limb.len(), chain.moduli.len());
        for (residues, &modulus) in rns.residues_by_limb.iter().zip(&chain.moduli) {
            assert_eq!(residues.len(), params.degree());
            assert!(residues.iter().all(|&residue| residue < modulus));
        }

        let reconstructed = chain
            .reconstruct_polynomial(&params, &rns)
            .expect("reconstruct RNS polynomial");
        assert_eq!(
            reconstructed,
            coefficients
                .iter()
                .map(|&coefficient| u128::from(coefficient))
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn rns_polynomial_rejects_malformed_shapes_and_residues() {
        let params = ram_lfe_bfv_parameters_v1();
        let chain = registered_bfv_rns_modulus_chain(&params).expect("registered chain");
        let coefficients = vec![0; params.degree()];
        let rns = chain
            .decompose_polynomial(&params, &coefficients)
            .expect("decompose zero polynomial");

        let mut wrong_limb_count = rns.clone();
        wrong_limb_count.residues_by_limb.pop();
        let err = chain
            .reconstruct_polynomial(&params, &wrong_limb_count)
            .expect_err("RNS limb-count drift must be rejected");
        assert!(
            err.to_string()
                .contains(&format!("expected {} limbs", chain.moduli.len()))
        );

        let mut wrong_limb_len = rns.clone();
        wrong_limb_len.residues_by_limb[0].pop();
        let err = chain
            .reconstruct_polynomial(&params, &wrong_limb_len)
            .expect_err("RNS limb length drift must be rejected");
        assert!(err.to_string().contains("polynomial_degree"));

        let mut out_of_range = rns.clone();
        out_of_range.residues_by_limb[0][0] = chain.moduli[0];
        let err = chain
            .reconstruct_polynomial(&params, &out_of_range)
            .expect_err("RNS residues must be reduced modulo their limb");
        assert!(err.to_string().contains("outside modulus"));

        let mut outside_ciphertext_modulus = coefficients;
        outside_ciphertext_modulus[0] = params.ciphertext_modulus;
        let err = chain
            .decompose_polynomial(&params, &outside_ciphertext_modulus)
            .expect_err("BFV coefficients must stay inside ciphertext modulus");
        assert!(err.to_string().contains("outside ciphertext modulus"));
    }

    #[test]
    fn rns_basis_extension_preserves_source_product_coefficients() {
        let params = rns_exact_params();
        let source_chain = BfvRnsModulusChain {
            moduli: vec![73, 89],
        };
        let target_chain = rns_exact_chain();
        let source_product = source_chain.product().expect("source product");
        let source_coefficients = vec![
            u128::from(params.ciphertext_modulus) + 7,
            source_product - 1,
        ];
        assert!(
            source_coefficients
                .iter()
                .any(|&coefficient| coefficient >= u128::from(params.ciphertext_modulus)),
            "basis-extension regression must cover values outside the ciphertext modulus"
        );
        let source_rns = BfvRnsPolynomial {
            residues_by_limb: source_chain
                .moduli
                .iter()
                .map(|&modulus| {
                    source_coefficients
                        .iter()
                        .map(|&coefficient| {
                            u64::try_from(coefficient % u128::from(modulus))
                                .expect("residue fits u64")
                        })
                        .collect()
                })
                .collect(),
        };

        let extended = source_chain
            .basis_extend_polynomial(&params, &source_rns, &target_chain)
            .expect("basis-extend source polynomial");
        assert_eq!(extended.residues_by_limb.len(), target_chain.moduli.len());
        let reconstructed = target_chain
            .reconstruct_polynomial(&params, &extended)
            .expect("reconstruct extended polynomial");
        assert_eq!(reconstructed, source_coefficients);

        let err = target_chain
            .basis_extend_polynomial(&params, &extended, &source_chain)
            .expect_err("narrow target basis-extension must reject aliasing");
        assert!(
            err.to_string().contains("target product"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn rns_target_limb_basis_extension_accepts_narrower_target_product() {
        let params = rns_exact_params();
        let source_chain = rns_exact_chain();
        let target_chain = BfvRnsModulusChain {
            moduli: vec![73, 89],
        };
        let source_product = source_chain.product().expect("source product");
        let target_product = target_chain.product().expect("target product");
        assert!(
            source_product > target_product,
            "regression must cover target limbs that cannot reconstruct source representatives"
        );
        let source_coefficients = vec![source_product - 1, target_product + 17];
        let source_rns = BfvRnsPolynomial {
            residues_by_limb: source_chain
                .moduli
                .iter()
                .map(|&modulus| {
                    source_coefficients
                        .iter()
                        .map(|&coefficient| {
                            u64::try_from(coefficient % u128::from(modulus))
                                .expect("residue fits u64")
                        })
                        .collect()
                })
                .collect(),
        };

        let err = source_chain
            .basis_extend_polynomial(&params, &source_rns, &target_chain)
            .expect_err("exact reconstructable basis extension must reject a narrow target");
        assert!(
            err.to_string().contains("target product"),
            "unexpected error: {err}"
        );
        let malformed_source_rns = BfvRnsPolynomial {
            residues_by_limb: vec![vec![0]],
        };
        let err = source_chain
            .basis_extend_polynomial(&params, &malformed_source_rns, &target_chain)
            .expect_err("exact basis extension must reject target coverage before source shape");
        assert!(
            err.to_string().contains("target product"),
            "unexpected error: {err}"
        );

        let extended = source_chain
            .basis_extend_polynomial_target_limbs(&params, &source_rns, &target_chain)
            .expect("target-limb basis extension accepts a narrow target");
        for (target_limb, &modulus) in extended.residues_by_limb.iter().zip(&target_chain.moduli) {
            let expected = source_coefficients
                .iter()
                .map(|&coefficient| {
                    u64::try_from(coefficient % u128::from(modulus)).expect("residue fits u64")
                })
                .collect::<Vec<_>>();
            assert_eq!(target_limb, &expected);
        }
        let reconstructed = target_chain
            .reconstruct_polynomial(&params, &extended)
            .expect("reconstruct target-limb residues");
        let expected_mod_target = source_coefficients
            .iter()
            .map(|&coefficient| coefficient % target_product)
            .collect::<Vec<_>>();
        assert_eq!(reconstructed, expected_mod_target);
        assert_ne!(
            reconstructed, source_coefficients,
            "narrow target reconstruction must remain visibly lossy"
        );
    }

    #[test]
    fn rns_key_switch_digit_polynomials_survive_basis_extension() {
        let params = rns_exact_params();
        let source_chain = BfvRnsModulusChain {
            moduli: vec![73, 89],
        };
        let target_chain = rns_exact_chain();
        let switching_component = vec![54, 37];
        let source_digits = source_chain
            .decompose_key_switch_component_polynomial(&params, &switching_component)
            .expect("decompose key-switch component into RNS digits");
        let expected_digits: [Vec<u64>; 2] = [vec![6, 5], vec![3, 2]];
        assert_eq!(source_digits.len(), expected_digits.len());
        for (digit, expected) in source_digits.iter().zip(&expected_digits) {
            assert_eq!(
                source_chain
                    .reconstruct_polynomial(&params, digit)
                    .expect("reconstruct source digit"),
                expected
                    .iter()
                    .map(|&coefficient| u128::from(coefficient))
                    .collect::<Vec<_>>()
            );
        }
        let target_digits = source_digits
            .iter()
            .map(|digit| {
                source_chain.basis_extend_key_switch_digit_polynomial(&params, digit, &target_chain)
            })
            .collect::<Result<Vec<_>, BfvError>>()
            .expect("basis-extend key-switch digits");
        let target_digits_from_target_limbs = source_digits
            .iter()
            .map(|digit| {
                source_chain.basis_extend_polynomial_target_limbs(&params, digit, &target_chain)
            })
            .collect::<Result<Vec<_>, BfvError>>()
            .expect("target-limb basis extension preserves key-switch digits");
        assert_eq!(target_digits_from_target_limbs, target_digits);
        validate_rns_key_switch_digit_polynomials(
            &params,
            &target_chain,
            &target_digits,
            "basis-extended key-switch digits",
        )
        .expect("basis-extended digits remain canonical");
        let mut truncated_target_digits = target_digits.clone();
        truncated_target_digits.pop();
        let err = validate_rns_key_switch_digit_polynomials(
            &params,
            &target_chain,
            &truncated_target_digits,
            "basis-extended key-switch digits",
        )
        .expect_err("digit-count drift must be rejected");
        assert!(
            err.to_string().contains("expected 2 decomposition digits"),
            "unexpected error: {err}"
        );
        let mut short_limb_target_digits = target_digits.clone();
        short_limb_target_digits[0].residues_by_limb[0].pop();
        let err = validate_rns_key_switch_digit_polynomials(
            &params,
            &target_chain,
            &short_limb_target_digits,
            "basis-extended key-switch digits",
        )
        .expect_err("digit limb polynomial-degree drift must be rejected");
        assert!(
            err.to_string().contains("expected polynomial_degree 2"),
            "unexpected error: {err}"
        );
        let mut missing_limb_target_digits = target_digits.clone();
        missing_limb_target_digits[0].residues_by_limb.pop();
        let err = validate_rns_key_switch_digit_polynomials(
            &params,
            &target_chain,
            &missing_limb_target_digits,
            "basis-extended key-switch digits",
        )
        .expect_err("digit RNS limb-count drift must be rejected");
        assert!(
            err.to_string().contains("expected 3 limbs"),
            "unexpected error: {err}"
        );

        let (_, _, relinearization_key) =
            keygen_from_seed(&params, b"bfv-rns-basis-key-switch-keygen").expect("keygen");
        let c0 = vec![13, 21];
        let c1 = vec![8, 34];
        let scalar = key_switch(
            &params,
            &relinearization_key.entries,
            &c0,
            &c1,
            &switching_component,
        )
        .expect("scalar key switch");
        let rns_from_component = key_switch_rns_exact(
            &params,
            &target_chain,
            &relinearization_key.entries,
            &c0,
            &c1,
            &switching_component,
        )
        .expect("RNS key switch from scalar component");
        let rns_from_digits = key_switch_rns_exact_with_digit_polynomials(
            &params,
            &target_chain,
            &relinearization_key.entries,
            &c0,
            &c1,
            &target_digits,
        )
        .expect("RNS key switch from basis-extended digits");
        let rns_from_basis_extension = key_switch_rns_exact_with_basis_extension(
            &params,
            &source_chain,
            &target_chain,
            &relinearization_key.entries,
            &c0,
            &c1,
            &switching_component,
        )
        .expect("RNS key switch with explicit basis extension");
        assert_eq!(rns_from_component, scalar);
        assert_eq!(rns_from_digits, scalar);
        assert_eq!(rns_from_basis_extension, scalar);

        let wide_source_chain = BfvRnsModulusChain {
            moduli: vec![73, 89, 97, 113],
        };
        assert!(
            wide_source_chain.product().expect("wide source product")
                > target_chain.product().expect("target product"),
            "wide source regression must exceed the evaluator target product"
        );
        let wide_source_digits = wide_source_chain
            .decompose_key_switch_component_polynomial(&params, &switching_component)
            .expect("decompose key-switch component in wider source chain");
        let err = wide_source_chain
            .basis_extend_polynomial(&params, &wide_source_digits[0], &target_chain)
            .expect_err("general polynomial basis extension must reject narrower targets");
        assert!(
            err.to_string().contains("target product"),
            "unexpected error: {err}"
        );
        let target_digits_from_wide = wide_source_digits
            .iter()
            .map(|digit| {
                wide_source_chain.basis_extend_key_switch_digit_polynomial(
                    &params,
                    digit,
                    &target_chain,
                )
            })
            .collect::<Result<Vec<_>, BfvError>>()
            .expect("digit basis extension accepts a narrower target product");
        let target_limb_digits_from_wide = wide_source_digits
            .iter()
            .map(|digit| {
                wide_source_chain.basis_extend_polynomial_target_limbs(
                    &params,
                    digit,
                    &target_chain,
                )
            })
            .collect::<Result<Vec<_>, BfvError>>()
            .expect("target-limb basis extension accepts a narrower target product");
        assert_eq!(target_digits_from_wide, target_digits);
        assert_eq!(target_limb_digits_from_wide, target_digits);
        let err = key_switch_rns_exact_with_basis_extension(
            &params,
            &wide_source_chain,
            &target_chain,
            &relinearization_key.entries,
            &c0,
            &c1,
            &switching_component,
        )
        .expect_err("key-switch basis extension must reject source chains outside the evaluator");
        assert!(
            err.to_string().contains("prefix of the evaluator chain"),
            "unexpected error: {err}"
        );

        let alien_source_chain = BfvRnsModulusChain {
            moduli: vec![73, 97],
        };
        alien_source_chain
            .validate_for_parameters(&params)
            .expect("alien source chain is structurally valid but not the evaluator prefix");
        let err = key_switch_rns_exact_with_basis_extension(
            &params,
            &alien_source_chain,
            &target_chain,
            &relinearization_key.entries,
            &c0,
            &c1,
            &switching_component,
        )
        .expect_err("key-switch basis extension must reject non-prefix source chains");
        assert!(
            err.to_string().contains("prefix of the evaluator chain"),
            "unexpected error: {err}"
        );

        let digit_product = target_chain
            .multiply_rns_polynomial_by_ciphertext_modulus_polynomial_negacyclic_exact(
                &params,
                &target_digits[0],
                &relinearization_key.entries[0].b,
            )
            .expect("multiply RNS digit by evaluation-key component");
        let scalar_digit_product = target_chain
            .multiply_ciphertext_modulus_polynomials_negacyclic_exact(
                &params,
                &expected_digits[0],
                &relinearization_key.entries[0].b,
            )
            .expect("multiply scalar digit by evaluation-key component");
        assert_eq!(digit_product, scalar_digit_product);

        let mut noncanonical_digit = target_digits.clone();
        let base = params.decomposition_base();
        for (limb, &modulus) in noncanonical_digit[0]
            .residues_by_limb
            .iter_mut()
            .zip(&target_chain.moduli)
        {
            limb[0] = base % modulus;
        }
        let err = validate_rns_key_switch_digit_polynomials(
            &params,
            &target_chain,
            &noncanonical_digit,
            "basis-extended key-switch digits",
        )
        .expect_err("noncanonical key-switch digits must be rejected");
        assert!(
            err.to_string().contains("exceeds decomposition base"),
            "unexpected error: {err}"
        );

        let mut noncanonical_source_digit = wide_source_digits[0].clone();
        for (limb, &modulus) in noncanonical_source_digit
            .residues_by_limb
            .iter_mut()
            .zip(&wide_source_chain.moduli)
        {
            limb[0] = base % modulus;
        }
        let err = wide_source_chain
            .basis_extend_key_switch_digit_polynomial(
                &params,
                &noncanonical_source_digit,
                &target_chain,
            )
            .expect_err("noncanonical source digits must not basis-extend");
        assert!(
            err.to_string().contains("exceeds decomposition base"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn rns_key_switch_basis_extension_rejects_digit_aliasing_source_chain() {
        let params = BfvParameters {
            polynomial_degree: 2,
            ciphertext_modulus: 60,
            plaintext_modulus: 5,
            decomposition_base_log: 8,
        };
        params.validate().expect("toy params are valid");
        let source_chain = BfvRnsModulusChain { moduli: vec![61] };
        let target_chain = rns_exact_chain();
        let zero = vec![0, 0];
        let switching_component = vec![59, 17];
        let malformed_component = vec![0];
        let err = source_chain
            .decompose_key_switch_component_polynomial(&params, &malformed_component)
            .expect_err("digit source chain coverage must be checked before component shape");
        assert!(
            err.to_string().contains("decomposition base"),
            "unexpected error: {err}"
        );
        let malformed_digit = BfvRnsPolynomial {
            residues_by_limb: Vec::new(),
        };
        let err = source_chain
            .basis_extend_key_switch_digit_polynomial(&params, &malformed_digit, &target_chain)
            .expect_err("digit source chain coverage must be checked before digit shape");
        assert!(
            err.to_string().contains("key-switch digit source product"),
            "unexpected error: {err}"
        );
        let wide_source_chain = BfvRnsModulusChain {
            moduli: vec![61, 257],
        };
        wide_source_chain
            .validate_for_parameters(&params)
            .expect("wide source chain covers decomposition base");
        let err = wide_source_chain
            .basis_extend_key_switch_digit_polynomial(&params, &malformed_digit, &source_chain)
            .expect_err("digit target chain coverage must be checked before digit shape");
        assert!(
            err.to_string().contains("key-switch digit target product"),
            "unexpected error: {err}"
        );
        let err = key_switch_rns_exact_with_basis_extension(
            &params,
            &source_chain,
            &target_chain,
            &[],
            &zero,
            &zero,
            &switching_component,
        )
        .expect_err("source chains that alias decomposition digits must be rejected");
        assert!(
            err.to_string().contains("decomposition base"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn rns_polynomial_ring_operations_match_scalar_mod_chain_product() {
        let params = ram_lfe_bfv_parameters_v1();
        let chain = registered_bfv_rns_modulus_chain(&params).expect("registered chain");
        let product = chain.product().expect("chain product");
        let lhs_coefficients = (0..params.degree())
            .map(|index| {
                let value = (u128::try_from(index + 3).expect("index fits")
                    * u128::from(RAM_LFE_BFV_PLAINTEXT_MODULUS + 11))
                    % u128::from(params.ciphertext_modulus);
                u64::try_from(value).expect("lhs coefficient fits")
            })
            .collect::<Vec<_>>();
        let rhs_coefficients = (0..params.degree())
            .map(|index| {
                let value = (u128::try_from(index + 5).expect("index fits")
                    * u128::from(RAM_LFE_BFV_PLAINTEXT_MODULUS + 29))
                    % u128::from(params.ciphertext_modulus);
                u64::try_from(value).expect("rhs coefficient fits")
            })
            .collect::<Vec<_>>();
        let lhs = chain
            .decompose_polynomial(&params, &lhs_coefficients)
            .expect("decompose lhs");
        let rhs = chain
            .decompose_polynomial(&params, &rhs_coefficients)
            .expect("decompose rhs");

        let added = chain
            .add_rns_polynomials(&params, &lhs, &rhs)
            .expect("add RNS polynomials");
        let reconstructed_add = chain
            .reconstruct_polynomial(&params, &added)
            .expect("reconstruct RNS sum");
        let expected_add = lhs_coefficients
            .iter()
            .zip(&rhs_coefficients)
            .map(|(&left, &right)| (u128::from(left) + u128::from(right)) % product)
            .collect::<Vec<_>>();
        assert_eq!(reconstructed_add, expected_add);

        let multiplied = chain
            .multiply_rns_polynomials_negacyclic(&params, &lhs, &rhs)
            .expect("multiply RNS polynomials");
        let reconstructed_product = chain
            .reconstruct_polynomial(&params, &multiplied)
            .expect("reconstruct RNS product");
        let mut expected_product = vec![0_u128; params.degree()];
        for (lhs_index, &left) in lhs_coefficients.iter().enumerate() {
            for (rhs_index, &right) in rhs_coefficients.iter().enumerate() {
                let term = (u128::from(left) * u128::from(right)) % product;
                let raw_index = lhs_index + rhs_index;
                if raw_index >= params.degree() {
                    let index = raw_index - params.degree();
                    expected_product[index] = (expected_product[index] + product - term) % product;
                } else {
                    expected_product[raw_index] = (expected_product[raw_index] + term) % product;
                }
            }
        }
        assert_eq!(reconstructed_product, expected_product);
    }

    #[test]
    fn rns_negacyclic_ntt_limb_products_match_scalar_baseline() {
        let params = ram_lfe_bfv_parameters_v1();
        for &modulus in &RAM_LFE_BFV_RNS_MODULI_V1 {
            let lhs = (0..params.degree())
                .map(|index| {
                    let index = u64::try_from(index).expect("index fits");
                    ((index + 7) * (index + 11) * 17) % modulus
                })
                .collect::<Vec<_>>();
            let rhs = (0..params.degree())
                .map(|index| {
                    let index = u64::try_from(index).expect("index fits");
                    ((index + 5) * (index + 19) * 23) % modulus
                })
                .collect::<Vec<_>>();

            let ntt = try_multiply_rns_limb_negacyclic_ntt(&params, &lhs, &rhs, modulus)
                .expect("registered RNS limb must support negacyclic NTT");
            let scalar = multiply_rns_limb_negacyclic_scalar(&params, &lhs, &rhs, modulus);
            assert_eq!(ntt, scalar, "RNS limb {modulus} NTT product");
        }
    }

    #[test]
    fn rns_negacyclic_multiplication_falls_back_for_non_ntt_limb() {
        let params = BfvParameters {
            polynomial_degree: 8,
            ciphertext_modulus: 45,
            plaintext_modulus: 5,
            decomposition_base_log: 4,
        };
        let modulus = 19;
        let lhs = (0..params.degree())
            .map(|index| u64::try_from(index + 3).expect("index fits") % modulus)
            .collect::<Vec<_>>();
        let rhs = (0..params.degree())
            .map(|index| (u64::try_from(index + 5).expect("index fits") * 3) % modulus)
            .collect::<Vec<_>>();

        assert!(
            try_multiply_rns_limb_negacyclic_ntt(&params, &lhs, &rhs, modulus).is_none(),
            "non-NTT limb must not enter the NTT path"
        );
        assert_eq!(
            multiply_rns_limb_negacyclic(&params, &lhs, &rhs, modulus),
            multiply_rns_limb_negacyclic_scalar(&params, &lhs, &rhs, modulus)
        );
    }

